static quint32 u32(const QByteArray &b,int n){return qFromLittleEndian<quint32>(b.constData()+n);}
static quint16 u16(const QByteArray &b,int n){return qFromLittleEndian<quint16>(b.constData()+n);}
static QByteArray slice(quint32 seq,int flags,QByteArray data){QByteArray s(12,0);s.replace(0,4,"XMIP");qToLittleEndian(seq,s.data()+4);s[8]=1;s[9]=char(flags);return s+data;}
