 void parser(){QVERIFY(validSerial("exampleSN12345678"));QVERIFY(!validSerial("a.b.c"));QVERIFY(!validSerial(QString(65,'a')));auto p=packet(1525,32,0x2014);putText(p,4,24,"192.0.2.3");qToLittleEndian<quint16>(8765,p.data()+28);auto e=endpoint(p,4,24,28);QCOMPARE(e.address.toString(),QString("192.0.2.3"));QCOMPARE(e.port,8765);QVERIFY_EXCEPTION_THROWN(endpoint(p.left(29),4,24,28),std::runtime_error);QVERIFY_EXCEPTION_THROWN(putText(p,4,5,"overflow"),std::runtime_error);}
